const menu=document.querySelector('.menu-toggle'),nav=document.querySelector('#main-nav');
menu?.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Close navigation':'Open navigation');nav.classList.toggle('is-open',open)});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&nav?.classList.contains('is-open')){menu.click();menu.focus()}});
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function authorHTML(s){return esc(s).replace(/\bJ\.? Hu\b|\bHu, J\b/g,'<strong>$&</strong>')}
function row(r){const badge=r.type==='professional'?'<span class="pub-badge">Featured as Cover Article</span>':r.title.includes('Tradeoff of CO')?'<span class="pub-badge">Cover article</span>':r.title.startsWith('Nitrous oxide dynamics')?'<span class="pub-badge">Wiley Top Cited Article 2020–2021</span>':'';return `<article class="publication">${r.label?`<p class="pub-year-tag">${esc(r.label)} · ${esc(r.year)}</p>`:''}<h3>${r.url?`<a href="${esc(r.url)}" target="_blank" rel="noopener">${esc(r.title)}</a>`:esc(r.title)}</h3><p class="authors">${authorHTML(r.authors)}</p>${r.venue?`<p class="journal">${esc(r.venue)}</p>`:''}<div class="pub-links">${r.url?`<a href="${esc(r.url)}" target="_blank" rel="noopener">${r.type==='dataset'?'View dataset':'Read article'}</a>`:''}${badge}</div></article>`}
async function loadPublications(){const list=document.querySelector('#publication-list'),recent=document.querySelector('#recent-publications');if(!list&&!recent)return;try{const res=await fetch(list ? 'publications.json?v=research-areas' : 'publications.json');if(!res.ok)throw Error('fetch');const raw=await res.json(),data=raw.sort((a,b)=>Number(b.year)-Number(a.year));if(recent){recent.innerHTML=data.filter(x=>x.type==='journal').slice(0,3).map(r=>`<article class="recent-pub"><span class="pub-year-tag">${esc(r.year)} · JOURNAL ARTICLE</span><h3>${esc(r.title)}</h3><p>${esc(r.journal)}</p><a class="text-link" href="${esc(r.url)}" target="_blank" rel="noopener">Read article</a></article>`).join('')}if(!list)return;const search=document.querySelector('#pub-search'),year=document.querySelector('#pub-year'),area=document.querySelector('#pub-area'),count=document.querySelector('#pub-count');const years=[...new Set(data.map(r=>r.year))].sort((a,b)=>Number(b)-Number(a));year.innerHTML+=[...years].map(y=>`<option value="${esc(y)}">${esc(y)}</option>`).join('');const params=new URLSearchParams(location.search);search.value=params.get('q')||'';area.value=[...area.options].some(option=>option.value===params.get('area'))?params.get('area'):'';function render(){const q=search.value.trim().toLowerCase();const items=data.filter(r=>(!q||r.citation.toLowerCase().includes(q))&&(!year.value||r.year===year.value)&&(!area.value||r.research_areas?.includes(area.value)));document.querySelectorAll('.pub-jumps a').forEach(a=>{const kinds={'#journal-articles':['journal'],'#other-publications':['editorial','professional'],'#public-dataset':['dataset']};a.hidden=!items.some(r=>kinds[a.hash].includes(r.type))});count.textContent=q||year.value||area.value?`${items.length} of ${data.length} entries`:`${data.filter(r=>r.type==='journal').length} journal articles · 2 other publications · 1 public dataset`;if(!items.length){list.innerHTML='<div class="empty-state"><h3>No matching publications</h3><p>Try a different keyword, research area, or year.</p><button id="clear-filters">Clear filters</button></div>';document.querySelector('#clear-filters').onclick=()=>{search.value='';year.value='';area.value='';render();search.focus()};return}const journals=items.filter(r=>r.type==='journal');list.innerHTML=(journals.length?'<h2 id="journal-articles">Journal Articles</h2>':'')+years.map(y=>{const group=journals.filter(r=>r.year===y);return group.length?`<section class="pub-year-group" aria-label="Publications from ${esc(y)}"><h2>${esc(y)}</h2><div>${group.map(row).join('')}</div></section>`:''}).join('')+[['other-publications','Other Publications',['editorial','professional']],['public-dataset','Public Dataset',['dataset']]].map(([id,title,types])=>{const group=items.filter(r=>types.includes(r.type));return group.length?`<section class="pub-extra" id="${id}"><h2>${title}</h2>${group.map(row).join('')}</section>`:''}).join('')}search.addEventListener('input',render);year.addEventListener('change',render);area.addEventListener('change',render);render()}catch(e){const target=list||recent;target.innerHTML='<p>Publications could not load. Please refresh this page or <a href="https://scholar.google.com/citations?user=1auhR6QAAAAJ">visit Google Scholar</a>.</p>';const count=document.querySelector('#pub-count');if(count)count.textContent='Publication list unavailable'}}loadPublications();
